-- LOCO game key and used-game marketplace upgrade (MySQL 8.x)
-- Import into EXISTING loco_db after backing it up. Never reimport the root loco_db.sql.
-- Safe to rerun. Existing game purchases, library rows and item marketplace are preserved.
-- Compatibility: legacy LOCO databases can have different parent table column
-- types / storage engines. Foreign keys are intentionally omitted here to avoid
-- MySQL Error 1215; PHP performs owner verification and transactional transfer.
-- This is a classroom sandbox, not a production financial/DRM platform.
-- License keys are generated by PHP when the owner opens the Library or lists a game;
-- these are LOCO-only simulated keys and cannot activate any third-party game.
SET @loco_add_license_key = (
  SELECT IF(COUNT(*) = 0,
   'ALTER TABLE library ADD COLUMN license_key CHAR(24) NULL',
   'SELECT 1')
  FROM information_schema.COLUMNS
  WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'library'
    AND COLUMN_NAME = 'license_key'
);
PREPARE loco_stmt FROM @loco_add_license_key;
EXECUTE loco_stmt;
DEALLOCATE PREPARE loco_stmt;

SET @loco_add_license_unique = (
  SELECT IF(COUNT(*) = 0,
   'ALTER TABLE library ADD UNIQUE KEY uq_loco_library_license_key (license_key)',
   'SELECT 1')
  FROM information_schema.STATISTICS
  WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'library'
    AND INDEX_NAME = 'uq_loco_library_license_key'
);
PREPARE loco_stmt FROM @loco_add_license_unique;
EXECUTE loco_stmt;
DEALLOCATE PREPARE loco_stmt;

CREATE TABLE IF NOT EXISTS game_resale_listings (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  library_id INT NOT NULL,
  seller_id INT NOT NULL,
  game_id INT NOT NULL,
  buyer_id INT NULL,
  price DECIMAL(10,2) NOT NULL,
  status ENUM('active','sold','cancelled','removed') NOT NULL DEFAULT 'active',
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  sold_at TIMESTAMP NULL DEFAULT NULL,
  active_library_id INT GENERATED ALWAYS AS (CASE WHEN status = 'active' THEN library_id ELSE NULL END) STORED,
  UNIQUE KEY uq_loco_resale_active_library (active_library_id),
  KEY idx_loco_resale_active (status,created_at),
  KEY idx_loco_resale_seller (seller_id,status),
  KEY idx_loco_resale_game (game_id,status),
  KEY idx_loco_resale_library_history (library_id,id),
  KEY idx_loco_resale_buyer (buyer_id,id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
-- Closed listing rows remain in history; one active listing per owned license.
-- A buyer can relist the license later after ownership has been transferred.
